    ('98188ad2-9486-59a7-a41f-ce910abe1b09'::uuid, 'Quiz — Yo, tú, usted : et pourquoi on les omet', 'Espagnol', '1re', 'Les pronoms personnels sujets', '4359c26f-46e3-54fa-a857-558f6ed8e645'::uuid),
