    ('d93d40ec-6d96-5fa9-a860-e0c00d9b5781'::uuid, 'Quiz — Que, quien, el que, cuyo', 'Espagnol', '1re', 'Les pronoms relatifs', '001853a1-3401-5563-b593-f1fc58eefdba'::uuid),
