    ('6ba2b4b0-5c41-5570-ad89-507f9c71873f'::uuid, 'bc25f63f-fab9-5f36-8f89-cbd2a0537bce'::uuid, 'Au subjonctif, l’affaiblissement touche « nosotros » et « vosotros ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Pidamos*, *pidáis* — contrairement à la diphtongue.', 6),
