    ('40cf24a0-3265-53f9-84f4-49b43a75e83e'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, '« Cuando era pequeño, jugaba al fútbol » exprime une habitude.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’emploi principal de l’imparfait avec la description.', 3),
    ('0cc196a4-b11b-541b-94ec-62aaecda2f86'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, 'Dans « Llovía cuando salí », quel temps fait avancer l’action ?', 'mcq', '["Salí (passé simple)","Llovía (imparfait)","Les deux","Aucun"]'::jsonb, 0, 'L’imparfait pose le décor, le passé simple marque l’événement.', 4),
    ('ed67454f-2bf9-596f-aea1-8de861e79895'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, 'Quel est l’imparfait de « ver » ?', 'mcq', '["Veía","Vía","Veaba","Vía/vea"]'::jsonb, 0, 'Il se forme sur l’ancien infinitif *veer*.', 5),
    ('33989826-40f7-5ead-bf81-6dd7b8714c37'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, '« Ayer llovió » et « Ayer llovía » disent exactement la même chose.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le premier rapporte un fait, le second décrit un contexte.', 6),
    ('743ae871-eb75-5754-acaa-ef98d23fcb01'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, 'Que signifie « Quería pedirle un favor » dans une demande polie ?', 'mcq', '["Je voudrais vous demander un service","Je voulais et je ne veux plus","J’ai demandé un service","Je devrai demander un service"]'::jsonb, 0, 'L’imparfait de politesse atténue la demande.', 7),
    ('acb8c471-ada8-5216-9afa-00a9277578be'::uuid, '883574c9-a9fe-5ed8-be7b-c1576a037796'::uuid, 'L’imparfait peut exprimer une action en cours interrompue par une autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Mientras cenábamos, sonó el teléfono.*', 8),
    ('c64ecaa3-efe0-5949-820d-eb118de46470'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'Comment se forme le pretérito perfecto ?', 'mcq', '["Haber au présent + participe passé","Tener + participe passé","Ser + participe passé","Estar + gérondif"]'::jsonb, 0, '*He comido*, *has estudiado*.', 1),
    ('d36876aa-dc42-5bca-869c-880e809dbe4a'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'Quel marqueur appelle le pretérito perfecto ?', 'mcq', '["Hoy","Ayer","El año pasado","En 1990"]'::jsonb, 0, 'Comme *esta semana*, *este año*, *ya*, *todavía no*.', 2),
    ('5e47b592-9925-599c-9e8b-b0adc62a3d3b'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'Le participe passé s’accorde avec le sujet au pretérito perfecto.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec *haber*, jamais d’accord : *ellas han llegado*.', 3),
    ('b793901e-49b1-533f-8cf3-dac2fe060d0b'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, '« Este año he viajado mucho » est correct.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période n’est pas achevée : le passé composé s’impose.', 4),
