    ('f47c6b85-2a29-5514-99d7-f6196d3725b0'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'En Amérique latine, le passé simple absorbe souvent le passé composé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Hoy comí paella* y est courant, sans être une faute.', 6),
    ('d948d326-d0e8-5388-b96c-00ead395b4ec'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, 'Que peut-on intercaler entre « haber » et le participe ?', 'mcq', '["Rien","Un adverbe","Une négation","Un pronom"]'::jsonb, 0, 'Le bloc est soudé : *No lo he visto nunca*.', 7),
    ('0b2a10b9-a261-5c20-8b31-fcf6157e86c8'::uuid, 'ff50d8f6-8f39-5321-abca-07df54ce1c9a'::uuid, '« Nunca he estado en México » est un bilan de vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La période de référence est la vie entière, non achevée.', 8),
    ('4430fdbc-ded9-5b9c-8fc6-70faccd46840'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Quelles terminaisons prend le passé simple des verbes en -ar ?', 'mcq', '["-é, -aste, -ó, -amos, -asteis, -aron","-í, -iste, -ió…","-aba, -abas…","-aré, -arás…"]'::jsonb, 0, '*Hablé, hablaste, habló, hablamos, hablasteis, hablaron.*', 1),
    ('909dac1d-ff85-55f3-8a07-1791ee991954'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, '« Hablo » et « habló » se distinguent uniquement par l’accent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’un est un présent, l’autre un passé simple : l’accent est distinctif.', 2),
    ('be86aa12-472d-5023-8cf1-becd233709ed'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Quel est le passé simple de « tener » à la première personne ?', 'mcq', '["Tuve","Tení","Tuvé","Tenió"]'::jsonb, 0, 'Prétérit fort : radical *tuv-* et terminaisons sans accent.', 3),
    ('1837dc12-5e3e-578c-9a32-dff704d7199d'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Quelle est la troisième personne du pluriel de « decir » au passé simple ?', 'mcq', '["Dijeron","Dijieron","Decieron","Digieron"]'::jsonb, 0, 'Après un radical en -j, le i de la terminaison disparaît.', 4),
    ('59c46455-0d30-5d6e-a2a6-d6d8226c64b0'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, '« Ser » et « ir » ont la même forme au passé simple.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Fui, fuiste, fue…* : seul le contexte permet de trancher.', 5),
    ('7a7f79cf-4351-54e7-bce3-518f8a0cb2c9'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Quel marqueur appelle le passé simple ?', 'mcq', '["Ayer","Hoy","Esta semana","Todavía no"]'::jsonb, 0, 'Comme *anoche*, *el año pasado*, *en 1975*.', 6),
    ('80f8d1df-13b6-5170-9036-c8e02f7d16a9'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Quelle est la troisième personne de « dormir » au passé simple ?', 'mcq', '["Durmió","Dormió","Duermió","Durmó"]'::jsonb, 0, 'Les verbes en -ir portent l’affaiblissement aux deux 3es personnes.', 7),
    ('2810e582-4786-5bf9-a504-b950e628dfec'::uuid, 'dc98cf8b-d4ed-5e41-9c05-e109b262abc4'::uuid, 'Dans un récit, le passé simple fait avancer l’action.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’imparfait, lui, décrit le cadre : *Era de noche… De repente, sonó el timbre.*', 8),
    ('2fcb5111-e851-5188-b7e4-5cf85f999579'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Sur quoi se construit le futur simple espagnol ?', 'mcq', '["Sur l’infinitif entier","Sur le radical du présent","Sur le participe passé","Sur le passé simple"]'::jsonb, 0, '*Hablaré*, *comeré*, *viviré* : mêmes terminaisons pour les trois groupes.', 1),
    ('5dd3fcd7-976c-5173-b761-9cfc102c9441'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Quel est le futur de « tener » à la première personne ?', 'mcq', '["Tendré","Teneré","Tenré","Tendría"]'::jsonb, 0, 'Un d remplace la voyelle, comme dans *pondré*, *vendré*, *saldré*.', 2),
    ('ab4b059d-2fc6-525a-9fdf-e2eec22b16c9'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Le conditionnel se forme sur le même radical que le futur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec les terminaisons de l’imparfait en -ía : *tendría*, *haría*, *diría*.', 3),
    ('84b07904-f3b1-5bec-99e7-a7ccc7ea9fed'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Que met-on après « cuando » avec une valeur de futur ?', 'mcq', '["Le subjonctif présent","Le futur simple","L’indicatif présent","Le conditionnel"]'::jsonb, 0, '*Cuando llegues, llámame* — jamais « cuando llegarás ».', 4),
    ('e1052b09-b374-5a8e-92ba-59528f59e97b'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Quel est le futur de « hacer » ?', 'mcq', '["Haré","Haceré","Hará","Hicé"]'::jsonb, 0, 'Radical raccourci, comme *decir → diré*.', 5),
    ('fa074784-d6dc-5336-9ecb-9a323640d541'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, '« Serán las tres » exprime une probabilité sur le présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le futur de supposition : il doit être trois heures.', 6),
    ('b3fdfe45-daf4-5d59-8a5c-581be5fc6b6b'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, 'Quelle forme du futur ne porte pas d’accent écrit ?', 'mcq', '["Nosotros (hablaremos)","Yo","Tú","Ellos"]'::jsonb, 0, 'Toutes les autres en portent un : *hablaré, hablarás, hablará, hablaréis, hablarán*.', 7),
    ('2c7b90fc-ed45-5e04-8247-d0e940f23a7d'::uuid, 'cbc1f610-2c50-5628-8696-0b974e545572'::uuid, '« Ir a + infinitif » exprime l’intention ou l’imminence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '*Voy a estudiar* : le futur proche, très employé à l’oral.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('espagnol');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('espagnol')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 267 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 267 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
